import os,re
allf=set()
for root,dirs,files in os.walk('AlgebraicJacobian'):
    for f in files:
        if f.endswith('.lean'): allf.add(os.path.join(root,f))
allf.add('AlgebraicJacobian.lean')
imp=re.compile(r'^\s*import\s+([A-Za-z0-9_.]+)')
seen={'AlgebraicJacobian.lean'};st=['AlgebraicJacobian.lean']
while st:
    cur=st.pop()
    for line in open(cur,encoding='utf-8',errors='replace'):
        m=imp.match(line)
        if not m: continue
        mod=m.group(1)
        if not mod.startswith('AlgebraicJacobian'): continue
        p=mod.replace('.','/')+'.lean'
        if p in allf and p not in seen: seen.add(p); st.append(p)
un=sorted(allf-seen)
def sc(p):
    s=open(p,encoding='utf-8',errors='replace').read()
    out=[];i=0;d=0
    while i<len(s):
        if s.startswith('/-',i): d+=1;i+=2;continue
        if s.startswith('-/',i) and d>0: d-=1;i+=2;continue
        if d==0:
            if s.startswith('--',i):
                j=s.find('\n',i)
                if j<0: break
                i=j;continue
            out.append(s[i])
        i+=1
    return len(re.findall(r'(?<![A-Za-z0-9_.])sorry(?![A-Za-z0-9_!?])',''.join(out)))
print('total',len(allf),'rooted',len(seen),'unrooted',len(un))
tot=0
for p in un:
    c=sc(p)
    if c: print('  SORRY',c,p); tot+=c
print('unrooted files with sorry:',sum(1 for p in un if sc(p)))
# also total project sorries for context
allsorry=sum(sc(p) for p in allf)
print('project-wide sorry terms:',allsorry,'in',sum(1 for p in allf if sc(p)),'files')
for p in sorted(allf):
    c=sc(p)
    if c: print('   ',c,p,'ROOTED' if p in seen else 'UNROOTED')
